create or replace function public.get_owned_traveling_token_setup(p_nfc_public_token uuid) returns table(token_id uuid,token_code text,name text,mission text,status text,current_box_code text) language sql stable security definer set search_path='' as $$ select t.id,t.token_code,t.name,t.mission,t.status,b.serial_code from public.traveling_tokens t left join public.physical_treasure_boxes b on b.id=t.current_box_id where t.nfc_public_token=p_nfc_public_token and t.owner_id=auth.uid() limit 1; $$;
create or replace function public.save_traveling_token_draft(p_nfc_public_token uuid,p_name text,p_mission text) returns void language plpgsql security definer set search_path='' as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; update public.traveling_tokens set name=nullif(trim(p_name),''),mission=nullif(trim(p_mission),''),updated_at=now() where nfc_public_token=p_nfc_public_token and owner_id=auth.uid() and status in ('draft','in_circulation','in_transit'); if not found then raise exception 'Traveling Token not found or not owned by you'; end if; end; $$;
create or replace function public.start_traveling_token_circulation(p_nfc_public_token uuid,p_name text,p_mission text,p_box_code text) returns table(token_id uuid,token_code text,status text,current_box_code text) language plpgsql security definer set search_path='' as $$ declare v_token public.traveling_tokens%rowtype; v_box public.physical_treasure_boxes%rowtype; begin if auth.uid() is null then raise exception 'Authentication required'; end if; select * into v_token from public.traveling_tokens where nfc_public_token=p_nfc_public_token and owner_id=auth.uid() for update; if v_token.id is null then raise exception 'Traveling Token not found or not owned by you'; end if; if v_token.status<>'draft' then raise exception 'This Traveling Token is not ready for its first placement'; end if; if nullif(trim(p_name),'') is null then raise exception 'Give your Traveling Token a name'; end if; select * into v_box from public.physical_treasure_boxes where upper(serial_code)=upper(trim(p_box_code)) limit 1; if v_box.id is null then raise exception 'Treasure Box ID not found'; end if; if v_box.claim_status<>'claimed' or v_box.cache_id is null then raise exception 'That Treasure Box is not ready to receive a Traveling Token yet'; end if; insert into public.traveling_token_stops(traveling_token_id,physical_box_id,stop_number,arrived_by) values(v_token.id,v_box.id,1,auth.uid()); update public.traveling_tokens set name=trim(p_name),mission=nullif(trim(p_mission),''),status='in_circulation',current_box_id=v_box.id,circulation_started_at=coalesce(circulation_started_at,now()),updated_at=now() where id=v_token.id; return query select v_token.id,v_token.token_code,'in_circulation'::text,v_box.serial_code; end; $$;
revoke all on function public.get_owned_traveling_token_setup(uuid) from public; grant execute on function public.get_owned_traveling_token_setup(uuid) to authenticated; revoke all on function public.save_traveling_token_draft(uuid,text,text) from public; grant execute on function public.save_traveling_token_draft(uuid,text,text) to authenticated; revoke all on function public.start_traveling_token_circulation(uuid,text,text,text) from public; grant execute on function public.start_traveling_token_circulation(uuid,text,text,text) to authenticated;